create function pg_temp.check_ok(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end $$;
create function pg_temp.denied(statement text) returns void language plpgsql as $$ begin begin execute statement;exception when insufficient_privilege or check_violation or raise_exception or serialization_failure then return;end;raise exception 'Unexpectedly allowed: %',statement;end $$;
